'use client'

import { useEffect, useRef, useState } from 'react'

/**
 * An architecture diagram, framed from public/diagrams/.
 *
 * The diagrams are self-contained pages rather than React components: each one
 * is generated by a build script in diagrams/, which is also what checks that
 * no label overflows its box and no connector runs through a label. Porting
 * that output into the render tree would buy nothing a visitor can see, and
 * would put a second stylesheet on every page that has no diagram on it.
 *
 * One file serves both themes. A frame cannot reach inside to set one, so the
 * theme travels in the query string and the page follows the reader's own
 * system setting when it is absent. Changing it remounts the frame, which is
 * cheap: the page is a few kilobytes of inline SVG with no script in it.
 *
 * It only loads once it is near the viewport. A reader who never scrolls to a
 * diagram should not pay for it.
 */
export default function Diagram({
  name,
  alt,
}: {
  /** The basename in public/diagrams. */
  name: string
  /** What the diagram shows, for anyone who cannot see it. */
  alt: string
}) {
  const frame = useRef<HTMLDivElement>(null)
  const [theme, setTheme] = useState<'dark' | 'light' | null>(null)
  const [near, setNear] = useState(false)

  useEffect(() => {
    const read = (): 'dark' | 'light' => {
      const set = document.documentElement.getAttribute('data-theme')
      if (set === 'dark' || set === 'light') return set
      return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'
    }
    setTheme(read())

    const observer = new MutationObserver(() => setTheme(read()))
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] })

    const media = window.matchMedia('(prefers-color-scheme: dark)')
    const onMedia = () => setTheme(read())
    media.addEventListener('change', onMedia)

    return () => {
      observer.disconnect()
      media.removeEventListener('change', onMedia)
    }
  }, [])

  useEffect(() => {
    const node = frame.current
    if (!node) return
    const io = new IntersectionObserver(
      (entries) => {
        if (entries[entries.length - 1].isIntersecting) {
          setNear(true)
          io.disconnect()
        }
      },
      { rootMargin: '400px 0px' },
    )
    io.observe(node)
    return () => io.disconnect()
  }, [])

  return (
    <div ref={frame}>
      <div
        className="relative w-full overflow-hidden border border-[var(--rule)]"
        style={{ aspectRatio: '1000 / 860' }}
      >
        {near && theme ? (
          <iframe
            key={theme}
            src={`/diagrams/${name}.html?theme=${theme}`}
            title={alt}
            loading="lazy"
            scrolling="no"
            className="absolute inset-0 h-full w-full"
            style={{ border: 0 }}
          />
        ) : (
          <div className="absolute inset-0" aria-hidden />
        )}
      </div>
      <p className="sr-only">{alt}</p>
    </div>
  )
}
